Func<Type,List<string>> names = t => new FilteredElementCollector(doc).OfClass(t).Cast<Element>().Select(e=>e.Name).ToList();
var floorTypes = new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Cast<FloorType>().Select(f=>f.Name+" | "+Math.Round((f.GetCompoundStructure()?.GetWidth()??0)*304.8)).ToList();
var stairTypes = names(typeof(Autodesk.Revit.DB.Architecture.StairsType));
var railTypes = names(typeof(Autodesk.Revit.DB.Architecture.RailingType));
var lv2 = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l=>l.Name=="Level 2");
var plans = new FilteredElementCollector(doc).OfClass(typeof(ViewPlan)).Cast<ViewPlan>().Where(v=>!v.IsTemplate && v.GenLevel!=null && v.GenLevel.Id==lv2.Id).Select(v=>v.Name+" | "+v.ViewType).ToList();
var phases = names(typeof(Phase));
var mats = new FilteredElementCollector(doc).OfClass(typeof(Material)).Cast<Material>().Where(m=>m.Name.ToLower().Contains("concrete")||m.Name.ToLower().Contains("gypsum")||m.Name.ToLower().Contains("plaster")).Select(m=>m.Name).Take(15).ToList();
return new{floorTypes,stairTypes,railTypes,plans,phases,mats};
